import {esc,options,btn,link} from './views.js';
import {feedbackRequest,hasAccessCode,setAccessCode} from './ai-client.js';
const categories=[['policy','An AUI policy or prerequisite'],['program','A program sheet or minor requirement'],['recommendation','A recommendation or its explanation'],['other','Something else']];
const stages=[['direction','Degree, focus or minor'],['courses','Courses and electives'],['targets','Companies or exchange destinations'],['pace','Study pace or semesters']];
const states={pending:'Awaiting team review',confirmed:'Correction verified by the GoPlan team',dismissed:'Reviewed — not confirmed', 'needs-information':'More information needed',unconfirmed:'Submission not yet confirmed',withdrawn:'Withdrawn'};
const accessField=()=>!hasAccessCode()?'<label class="field">Demo access code<input id="ai-access-code" type="password" autocomplete="off"></label>':'';
const credentials=()=>{const field=document.querySelector('#ai-access-code');if(field?.value)setAccessCode(field.value);};
const key=workspace=>'goplan-feedback:'+workspace;
function receipts(workspace){try{return JSON.parse(localStorage.getItem(key(workspace))||'[]');}catch{return [];}}
function keep(workspace,item){const list=receipts(workspace).filter(r=>r.id!==item.id);localStorage.setItem(key(workspace),JSON.stringify([item,...list]));}
function forget(workspace,id){localStorage.setItem(key(workspace),JSON.stringify(receipts(workspace).filter(r=>r.id!==id)));}

export function ethicsPolicy(){return `<div class="ethics-policy"><p class="intro-copy">Your roadmap belongs to you. AI suggests; you choose.</p><ol class="ethics-steps"><li><strong>Advice grounded in evidence.</strong><p>GoPlan combines your goals with reviewed AUI requirements and relevant research. You review proposed changes before they replace a saved plan. Course availability and individual approvals still need confirmation.</p></li><li><strong>A personal, private workspace.</strong><p>Your name, email, answers, roadmap and progress are stored for your account and synced across devices. The admin dashboard lists profile details and activity dates; it does not show your private roadmap, answers or grades.</p></li><li><strong>Feedback with your permission.</strong><p>Report a mistake when you want the team to check it. Reports include your text and academic identifiers, without automatically attaching your name, grades or questionnaire. A person checks the evidence before confirming a correction.</p></li><li><strong>Learning from verified corrections.</strong><p>Only with your opt-in can a verified correction inform other users’ recommendations. This improves reference guidance; it does not retrain the underlying AI model.</p></li></ol><details class="quiet-details"><summary>Storage, AI use and withdrawal</summary><h3>Account and storage</h3><p>GoPlan verifies your email when creating or recovering your account; later sign-ins use email and password. Your cloud profile and roadmaps remain until you delete them in Account → Privacy & account data. A browser copy helps recover unsynced edits. Signing out clears your account’s cached roadmaps on this browser; it does not delete cloud plans, older device-only plans or downloaded files.</p><h3>What the AI receives</h3><p>Groq receives your questionnaire, academic choices and relevant change requests. Continuing-student planning and replanning also include course codes, status and semester placement. Your name, sign-in email, exact GPA, grades and private progress notes are excluded from the automatic payload. A yes/no indicator of accelerated-load eligibility may be included. Anything you type into a request is sent as written, so avoid sensitive details. Public-topic research may supplement the reviewed academic data. Groq’s browser search uses Exa; only general topic queries are intended for search, with email addresses and phone numbers removed.</p><h3>What the dashboard measures</h3><p>The private dashboard shows registered names, emails, join dates and last account activity. Separately, it shows aggregate adviser outcomes, response time, provider usage, plan saves, accepted updates and Excel requests. Those counters contain no names or answers and do not measure unique visitors. Counters older than 90 days are deleted on the next measurement write.</p><h3>Reports and withdrawal</h3><p>Submitting a report stores it privately for team review and does not itself call the AI. Choosing “Review this with my adviser” sends its text with the planning context. Reports and review history expire after 90 days; expired corrections stop being used immediately and records are removed on the next report operation.</p><p>Open Your workspace → My mistake reports from the same browser and roadmap to withdraw a report. Its private receipt stays in that browser and is not synced with your account. Withdrawal removes the report and review history and stops its correction from appearing in future requests; it cannot undo advice already delivered or a request in progress. Deleting your account does not withdraw these separate reports. Withdraw them first if you want both removed.</p><h3>Your controls</h3><p>Account lets you edit your name, download your personal data, sign out or delete your GoPlan profile and cloud roadmaps. Authentication providers retain their own sign-in records under their policies. Authorized operators maintain the service; the student dashboard does not make your plan public.</p><a href="/privacy.html" target="_blank" rel="noopener">Full privacy notice</a></details></div>`;}


export function openMistakeReport({plan,workspace,modal,head,onReconsider}){
 const academic=Object.fromEntries(['program','track','secondTrack','minor'].map(k=>[k,plan.profile[k]||'']));
 modal(`${head('Help your adviser get it right','Tell us about a recommendation you believe is mistaken.')}<form id="mistake-form"><div class="field-grid"><label class="field">What went wrong?<select name="category">${options(categories,'policy')}</select></label><label class="field">Which part of your plan?<select name="stage">${options(stages,'courses')}</select></label></div><label class="field">Describe the mistake<textarea name="issue" required minlength="10" maxlength="1000" rows="3" placeholder="The plan treats this course as optional, but my program sheet says it is required."></textarea></label><label class="field">What should happen instead? (optional)<textarea name="expected" maxlength="500" rows="2" placeholder="Explain the correction you would like the team to check."></textarea></label><label class="field">Supporting source (optional)<input name="evidence" maxlength="250" placeholder="AUI page link, or program sheet name and page"></label><details class="quiet-details"><summary>Academic context sent with this report</summary><p>${esc(plan.program.name)}</p><p class="small-note">${esc([academic.track,academic.secondTrack,academic.minor].filter(Boolean).join(' · ')||'No additional focus selected')}</p><p class="small-note">Only these academic identifiers and the report fields above are sent. Name, grades, goals and progress notes are excluded.</p></details><div class="feedback-consent"><label class="checkbox-row"><input name="share" type="checkbox" required><span>Send this report and its academic context to the GoPlan team for review.</span></label><label class="checkbox-row"><input name="improve" type="checkbox"><span>Also allow a verified correction to improve future recommendations for other users. <small>Optional. Your report still gets reviewed if you leave this off.</small></span></label></div><details class="quiet-details"><summary>How feedback is used</summary>${ethicsPolicy()}</details>${accessField()}<div id="feedback-result" role="status"></div><div class="modal-actions">${btn('close','Cancel')}<button class="button primary" type="submit">Send mistake report</button></div></form>`);
 const form=document.querySelector('#mistake-form');let pending=null,busy=false;
 form.addEventListener('submit',async event=>{
  event.preventDefault();if(busy)return;credentials();const data=new FormData(form),payload={category:data.get('category'),stage:data.get('stage'),issue:data.get('issue'),expected:data.get('expected'),evidence:data.get('evidence'),academic,consentShare:data.get('share')==='on',consentImprove:data.get('improve')==='on'};
  const fingerprint=JSON.stringify(payload);if(!pending||pending.fingerprint!==fingerprint)pending={id:crypto.randomUUID(),receiptToken:Array.from(crypto.getRandomValues(new Uint8Array(32)),x=>x.toString(16).padStart(2,'0')).join(''),fingerprint};
  const output=form.querySelector('#feedback-result'),button=form.querySelector('[type="submit"]');busy=true;for(const control of form.querySelectorAll('input,select,textarea,button[type=submit]'))control.disabled=true;output.textContent='Sending your report securely…';
  try{
   keep(workspace,{id:pending.id,receiptToken:pending.receiptToken,status:'unconfirmed',createdAt:new Date().toISOString()});
   const result=await feedbackRequest('',{...payload,id:pending.id,receiptToken:pending.receiptToken});keep(workspace,{...result,receiptToken:pending.receiptToken});
   if(!form.isConnected)return;
   modal(`${head('Your report is received','Thank you for helping us check the facts.')}<div class="feedback-receipt"><span class="tag">Awaiting team review</span><p>Your saved plan is unchanged. The team will check the evidence before confirming a correction.</p><p class="small-note">${payload.consentImprove?'You allowed a verified correction to improve future guidance.':'This report is for review only; you did not allow shared learning.'}</p><p class="small-note">Reference: <code>${esc(result.id)}</code></p></div><p>You can ask the adviser to reconsider this now. It will treat your report as an unverified claim and check it against the academic evidence.</p><div class="card-actions"><button class="button primary" id="reconsider-report">Review this with my adviser</button>${btn('close','Done')}</div>`);
   document.querySelector('#reconsider-report').addEventListener('click',()=>onReconsider(`Please review a possible mistake (report ${result.id}; not yet verified). ${payload.issue}\nRequested correction: ${payload.expected||'Please check the evidence.'}\nSource supplied by the student: ${payload.evidence||'None supplied.'}\nPreserve unaffected choices and explain any unresolved source conflict.`));
  }catch(error){if(form.isConnected){output.textContent=error.name==='TimeoutError'?'We could not confirm receipt. Your text is still here. Retry with the same report or check My reports.':error.message;if(error.code==='ACCESS_REQUIRED'&&!form.querySelector('#ai-access-code'))output.insertAdjacentHTML('beforeend',accessField());}}
  finally{busy=false;for(const control of form.querySelectorAll('input,select,textarea,button[type=submit]'))control.disabled=false;}
 });
}

export function openMyReports({workspace,modal,head}){
 const list=receipts(workspace);
 modal(`${head('My mistake reports','Check a review outcome or withdraw a report.')}<p class="small-note">Reports from this workspace are listed below. Status is checked with the backend when you open a report.</p>${accessField()}<div class="feedback-list">${list.map(r=>`<article class="feedback-receipt"><h3>${esc(states[r.status]||'Report received')}</h3><p class="small-note">${esc(new Date(r.createdAt).toLocaleDateString())} · ${esc(r.id.slice(0,8))}</p><button class="button secondary" data-open-report="${esc(r.id)}">Check report</button></article>`).join('')||'<p>No reports have been sent from this workspace.</p>'}</div><div id="reports-result" role="status"></div>`);
 for(const button of document.querySelectorAll('[data-open-report]'))button.addEventListener('click',async()=>{
  credentials();const r=list.find(r=>r.id===button.dataset.openReport),output=document.querySelector('#reports-result');button.disabled=true;output.textContent='Checking the review…';
  try{const current=await feedbackRequest('status',{id:r.id,receiptToken:r.receiptToken});keep(workspace,{...current,receiptToken:r.receiptToken});if(!button.isConnected)return;
   modal(`${head(states[current.status]||'Report status')}<div class="feedback-receipt"><p>${esc(current.reviewNote||'The GoPlan team has not completed the evidence review yet.')}</p>${current.correction?`<p><strong>Verified correction:</strong> ${esc(current.correction.text)}</p><p class="small-note">Reviewed against: ${current.correction.source?.url?link(current.correction.source.url,'AUI source'):esc((current.correction.source?.file||'Supplied document')+' · PDF page '+current.correction.source?.page)}</p>`:''}<p class="small-note">${current.learning==='reviewed-guidance'?'This verified correction is available to future adviser requests.':'No shared correction has been applied from this report.'}</p><p class="small-note">Expires ${esc(new Date(current.expiresAt).toLocaleDateString())} · Reference ${esc(current.id)}</p></div><p>Withdrawing removes your report and its review history from the backend and stops using its correction in future requests. Your saved plan stays as it is.</p><button id="withdraw-report" class="button secondary">Withdraw this report</button><div id="withdraw-result" role="status"></div>`);
   document.querySelector('#withdraw-report').addEventListener('click',async event=>{event.target.disabled=true;try{await feedbackRequest('withdraw',{id:r.id,receiptToken:r.receiptToken});forget(workspace,r.id);document.querySelector('#withdraw-result').textContent='Your report has been withdrawn and removed. Its correction will not be included in future requests.';event.target.hidden=true;}catch(error){document.querySelector('#withdraw-result').textContent=error.message;event.target.disabled=false;}});
  }catch(error){if(output.isConnected){output.textContent=error.message;if(error.code==='ACCESS_REQUIRED'&&!document.querySelector('#ai-access-code'))output.insertAdjacentHTML('beforeend',accessField());}button.disabled=false;}
 });
}
